template:
% 参数由系统自动注入：\def\ab{5} \def\ac{6} \def\anglea{60} \def\showangle{1} \def\rightmarka{0} \def\rightmarkb{0} \def\rightmarkc{0} \def\showd{0} \def\showe{0} \def\showf{0} \def\showmedianad{0} \def\showmidseg{0}
% 视觉归一化：把最长边缩放到 6（单位由 coordScale 决定），保证图形视觉大小稳定；
% 只缩放坐标，线宽、字体、虚线样式保持不变。
\pgfmathsetmacro{\figscale}{6 / max(\ab, \ac)}
% 辅助点圆点半径（绝对尺寸，不随图形缩放，保证视觉一致性）
\def\ptRad{1.6pt}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  % 三个顶点
  \coordinate (A) at (0,0);
  \coordinate (B) at (\ab,0);
  \pgfmathsetmacro{\Cx}{\ac*cos(\anglea)}
  \pgfmathsetmacro{\Cy}{\ac*sin(\anglea)}
  \coordinate (C) at (\Cx,\Cy);
  % 三边中点：D=BC中点, E=AC中点, F=AB中点
  \pgfmathsetmacro{\Dx}{(\ab + \Cx)/2}
  \pgfmathsetmacro{\Dy}{\Cy/2}
  \coordinate (D) at (\Dx,\Dy);
  \pgfmathsetmacro{\Ex}{\Cx/2}
  \pgfmathsetmacro{\Ey}{\Cy/2}
  \coordinate (E) at (\Ex,\Ey);
  \coordinate (F) at (\ab/2,0);
  % 三角形三边
  \draw[thick] (A) -- (B) -- (C) -- cycle;
  % ∠A 角弧（朝三角形内部，开直角记号时不画角弧）
  \ifnum\showangle>0
    \ifnum\rightmarka=0
      \pgfmathsetmacro{\arcr}{min(0.4, \ab*0.18, \ac*0.18)}
      \draw[thick] (\arcr,0) arc[start angle=0, end angle=\anglea, radius=\arcr];
    \fi
  \fi
  % ∠A 直角记号（小正方形两边，朝三角形内部，∠A=90 时使用）
  \ifnum\rightmarka>0
    \pgfmathsetmacro{\rmsz}{min(0.3, \ab*0.2, \ac*0.2)}
    \draw[thick] (\rmsz,0) -- (\rmsz,\rmsz) -- (0,\rmsz);
  \fi
  % ∠B 直角记号（B 在(\ab,0)，BA 沿-x，BC 斜向上）
  \ifnum\rightmarkb>0
    \pgfmathsetmacro{\rmszb}{min(0.3, \ab*0.2, \Cy*0.2)}
    \pgfmathsetmacro{\bclen}{sqrt((\Cx-\ab)^2 + \Cy^2)}
    \pgfmathsetmacro{\rmbax}{\ab - \rmszb}
    \pgfmathsetmacro{\rmbcx}{\ab + (\Cx-\ab)/\bclen*\rmszb}
    \pgfmathsetmacro{\rmbcy}{\Cy/\bclen*\rmszb}
    \pgfmathsetmacro{\rmbmx}{\rmbax + (\Cx-\ab)/\bclen*\rmszb}
    \pgfmathsetmacro{\rmbmy}{\Cy/\bclen*\rmszb}
    \draw[thick] (\rmbax,0) -- (\rmbmx,\rmbmy) -- (\rmbcx,\rmbcy);
  \fi
  % ∠C 直角记号（C 在(\Cx,\Cy)，沿 CA、CB 两边方向）
  \ifnum\rightmarkc>0
    \pgfmathsetmacro{\rmszc}{min(0.3, \ac*0.2, sqrt((\Cx-\ab)^2 + \Cy^2)*0.2)}
    \pgfmathsetmacro{\bclen}{sqrt((\Cx-\ab)^2 + \Cy^2)}
    \pgfmathsetmacro{\rmcax}{\Cx - \Cx/\ac*\rmszc}
    \pgfmathsetmacro{\rmcay}{\Cy - \Cy/\ac*\rmszc}
    \pgfmathsetmacro{\rmcbx}{\Cx + (\ab-\Cx)/\bclen*\rmszc}
    \pgfmathsetmacro{\rmcby}{\Cy - \Cy/\bclen*\rmszc}
    \pgfmathsetmacro{\rmcmx}{\rmcax + (\ab-\Cx)/\bclen*\rmszc}
    \pgfmathsetmacro{\rmcmy}{\rmcay - \Cy/\bclen*\rmszc}
    \draw[thick] (\rmcax,\rmcay) -- (\rmcmx,\rmcmy) -- (\rmcbx,\rmcby);
  \fi
  % 中线 AD（实线，从顶点 A 到 BC 中点 D）
  \ifnum\showmedianad>0
    \draw[thick] (A) -- (D);
  \fi
  % 中位线（虚线，连接 D-E-F-D 构成中位线三角形）
  \ifnum\showmidseg>0
    \draw[dashed] (D) -- (E);
    \draw[dashed] (E) -- (F);
    \draw[dashed] (F) -- (D);
  \fi
  % 中点处画实心小圆点（绝对半径，不随坐标缩放，明确标出边上有个点）
  \ifnum\showd>0
    \fill (D) circle [radius=\ptRad];
  \fi
  \ifnum\showe>0
    \fill (E) circle [radius=\ptRad];
  \fi
  \ifnum\showf>0
    \fill (F) circle [radius=\ptRad];
  \fi
  % 顶点标签
  \node[below left=3pt] at (A) {$A$};
  \node[below right=3pt] at (B) {$B$};
  \node[above=3pt] at (C) {$C$};
  % 中点标签：根据对应 bool 显示
  \ifnum\showd>0
    \node[above right=3pt] at (D) {$D$};
  \fi
  \ifnum\showe>0
    \node[left=3pt] at (E) {$E$};
  \fi
  \ifnum\showf>0
    \node[below=3pt] at (F) {$F$};
  \fi
\end{tikzpicture}
